// Presentation only: the repository retains its existing matching and ranking.
function reafolioSearchHighlights(title, content, tokens) {
  const escape = text => text.replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const fold = text => text.normalize('NFC').toLowerCase();
  const terms = {title: new Set(), content: new Set()};
  for (let token of tokens) {
    if (token.startsWith('-')) continue;
    const prefix = token.match(/^(title|content|tag|tags):/i);
    const field = prefix?.[1].toLowerCase() || '';
    if (prefix) token = token.slice(prefix[0].length);
    token = fold(token.replace(/^"|"$/g, ''));
    if (!token || token.startsWith('#') || field === 'tag' || field === 'tags') continue;
    if (field !== 'content') terms.title.add(token);
    if (field !== 'title') terms.content.add(token);
  }

  function rangesFor(text, needles, limit = 64) {
    if (!needles.size) return [];
    const normalized = text.normalize('NFC'), folded = normalized.toLowerCase();
    const ranges = [];
    for (const needle of needles) {
      // Bound result markup even for extremely repetitive notes or one-letter queries.
      let cursor = 0;
      for (let count = 0; count < limit; count++) {
        const start = folded.indexOf(needle, cursor);
        if (start < 0) break;
        ranges.push({start, end: start + needle.length});
        cursor = start + Math.max(1, needle.length);
      }
    }
    if (normalized !== text || folded.length !== text.length) {
      // NFC and length-changing lowercase mappings must not shift later highlights.
      const events = ranges.flatMap(range => [
        {offset:range.start, range, edge:'start'}, {offset:range.end, range, edge:'end'},
      ]).sort((a,b) => a.offset-b.offset);
      let cursor = 0, offset = 0;
      for (const part of new Intl.Segmenter(undefined, {granularity:'grapheme'}).segment(text)) {
        const next = offset + fold(part.segment).length, end = part.index + part.segment.length;
        while (cursor < events.length && events[cursor].offset <= next) {
          const event = events[cursor++];
          event.range[event.edge] = event.offset === next ? end :
            event.offset === offset || event.edge === 'start' ? part.index : end;
        }
        if (cursor === events.length) break;
        offset = next;
      }
    }
    ranges.sort((a,b) => a.start-b.start || b.end-a.end);
    const merged = [];
    for (const range of ranges) {
      const previous = merged[merged.length-1];
      if (previous && range.start <= previous.end) previous.end = Math.max(previous.end,range.end);
      else merged.push({...range});
    }
    return merged;
  }

  function render(text, ranges, start = 0, end = text.length) {
    let cursor = start, html = '';
    for (const range of ranges) {
      if (range.end <= start) continue;
      if (range.start >= end) break;
      const left = Math.max(start,range.start), right = Math.min(end,range.end);
      html += escape(text.slice(cursor,left)) + '<b class="match">' + escape(text.slice(left,right)) + '</b>';
      cursor = right;
    }
    return html + escape(text.slice(cursor,end));
  }

  function snippet(text, ranges) {
    if (!ranges.length) return escape(text.replace(/\s+/g,' ').slice(0,180));
    const fragments = [];
    for (const range of ranges) {
      let start = Math.max(0,range.start-35), end = Math.min(text.length,range.end+55);
      // Prefer complete surrounding words without expanding long CJK runs indefinitely.
      const leftLimit = Math.max(0,start-18), rightLimit = Math.min(text.length,end+18);
      while (start > leftLimit && /[\p{L}\p{N}\p{M}]/u.test(text[start-1]) && /[\p{L}\p{N}\p{M}]/u.test(text[start])) start--;
      while (end < rightLimit && /[\p{L}\p{N}\p{M}]/u.test(text[end-1]) && /[\p{L}\p{N}\p{M}]/u.test(text[end])) end++;
      if (start > 0 && /[\uDC00-\uDFFF]/.test(text[start])) start--;
      if (end < text.length && /[\uDC00-\uDFFF]/.test(text[end])) end++;
      const previous = fragments[fragments.length-1];
      if (previous && start <= previous.end && end-previous.start <= 200) previous.end = Math.max(previous.end,end);
      else fragments.push({start,end});
    }
    // Prefer useful, dense contexts, then present up to three in document order.
    const scored = fragments.map(fragment => ({...fragment, score:ranges.filter(range => range.start >= fragment.start && range.end <= fragment.end).length}));
    scored.sort((a,b) => b.score-a.score || a.start-b.start);
    const selected = [];
    for (const fragment of scored) {
      if (selected.some(other => fragment.start < other.end && fragment.end > other.start)) continue;
      selected.push(fragment);
      if (selected.length === 3) break;
    }
    selected.sort((a,b) => a.start-b.start);
    return selected.map((fragment,index) => {
      const prefix = index === 0 && fragment.start > 0 ? '...' : '';
      const suffix = index === selected.length-1 && fragment.end < text.length ? '...' : '';
      return prefix + render(text,ranges,fragment.start,fragment.end).replace(/\s+/g,' ').trim() + suffix;
    }).join('...');
  }

  const titleRanges = rangesFor(title,terms.title,256), contentRanges = rangesFor(content,terms.content);
  return {titleHighlights:render(title,titleRanges), contentHighlights:snippet(content,contentRanges)};
}
